import{_ as t,o,c as r,a3 as a}from"./chunks/framework.DBpCFmh2.js";const p=JSON.parse('{"title":"Shadow DOM 穿透","description":"Shadow DOM 是 Web Components 的核心隔离机制之一。","frontmatter":{"title":"Shadow DOM 穿透","description":"Shadow DOM 是 Web Components 的核心隔离机制之一。"},"headers":[],"relativePath":"网页增强工具/Shadow-DOM-穿透/index.md","filePath":"网页增强工具/Shadow-DOM-穿透/index.md","lastUpdated":null}'),i={name:"网页增强工具/Shadow-DOM-穿透/index.md"};function l(n,e,c,s,h,d){return o(),r("div",null,[...e[0]||(e[0]=[a(`<h1 id="shadow-dom-穿透" tabindex="-1">Shadow DOM 穿透 <a class="header-anchor" href="#shadow-dom-穿透" aria-label="Permalink to &quot;Shadow DOM 穿透&quot;">​</a></h1><details class="details custom-block"><summary>本文引用的源码文件</summary><p><strong>本文引用的文件</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/shadow-dom-utils.js" target="_blank" rel="noreferrer">src/content/shadow-dom-utils.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/page-interaction.js" target="_blank" rel="noreferrer">src/content/page-interaction.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/interaction-tools.js" target="_blank" rel="noreferrer">src/content/interaction-tools.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/page-tools.js" target="_blank" rel="noreferrer">src/content/page-tools.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/advanced-tools.js" target="_blank" rel="noreferrer">src/content/advanced-tools.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/selection-toolbar.js" target="_blank" rel="noreferrer">src/content/selection-toolbar.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/test/e2e/fixtures/shadow-dom-page.html" target="_blank" rel="noreferrer">test/e2e/fixtures/shadow-dom-page.html</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/test/unit/completion-evidence-content.unit.test.js" target="_blank" rel="noreferrer">test/unit/completion-evidence-content.unit.test.js</a></li></ul></details><h2 id="目录" tabindex="-1">目录 <a class="header-anchor" href="#目录" aria-label="Permalink to &quot;目录&quot;">​</a></h2><ol><li><a href="#引言">引言</a></li><li><a href="#项目结构中的-shadow-dom-能力定位">项目结构中的 Shadow DOM 能力定位</a></li><li><a href="#核心组件与职责划分">核心组件与职责划分</a></li><li><a href="#架构总览从工具调用到-shadow-root-遍历">架构总览：从工具调用到 Shadow Root 遍历</a></li><li><a href="#穿透算法详解">穿透算法详解</a></li><li><a href="#跨域-iframe-与安全边界">跨域 iframe 与安全边界</a></li><li><a href="#web-components-内部内容访问示例">Web Components 内部内容访问示例</a></li><li><a href="#性能缓存与内存泄漏防护">性能、缓存与内存泄漏防护</a></li><li><a href="#与现代前端框架的集成实践">与现代前端框架的集成实践</a></li><li><a href="#故障排查指南">故障排查指南</a></li><li><a href="#结论">结论</a></li></ol><h2 id="引言" tabindex="-1">引言 <a class="header-anchor" href="#引言" aria-label="Permalink to &quot;引言&quot;">​</a></h2><p>Shadow DOM 是 Web Components 的核心隔离机制之一。它把组件的内部结构、样式和事件处理封装在一个独立的文档片段中，宿主页面无法直接通过常规 <code>document.querySelector</code> 访问其内部节点。对浏览器扩展、自动化脚本、网页分析工具和智能体交互系统而言，这意味着必须实现“穿透”能力：递归进入 <code>shadowRoot</code>，同时兼容同源 <code>iframe</code>，并在权限受限或跨域场景下安全降级。</p><p>本仓库在扩展端 Content Script 层实现了完整的 Shadow DOM 穿透工具集，并在此基础上提供元素查询、文本提取、HTML 快照、选择范围获取、可见性判断、滚动收集以及基于 ref 的元素操作等上层能力。这些能力被多个工具模块复用，支撑了“精准操作任意前端框架页面”的目标。</p><h2 id="项目结构中的-shadow-dom-能力定位" tabindex="-1">项目结构中的 Shadow DOM 能力定位 <a class="header-anchor" href="#项目结构中的-shadow-dom-能力定位" aria-label="Permalink to &quot;项目结构中的 Shadow DOM 能力定位&quot;">​</a></h2><p>Shadow DOM 穿透能力集中在一个专用工具模块中，其他功能模块通过导入方式复用该能力，而不是各自重复实现。</p><pre class="mermaid">graph TB
shadow_utils[&quot;shadow-dom-utils.js&lt;br/&gt;Shadow DOM 与 iframe 深度工具&quot;] --&gt; page_interaction[&quot;page-interaction.js&lt;br/&gt;元素快照、ref 解析、交互树&quot;]
shadow_utils --&gt; interaction_tools[&quot;interaction-tools.js&lt;br/&gt;点击、填充、键盘、滚动、下拉&quot;]
shadow_utils --&gt; page_tools[&quot;page-tools.js&lt;br/&gt;页面文本、标题、链接、HTML 导出&quot;]
shadow_utils --&gt; advanced_tools[&quot;advanced-tools.js&lt;br/&gt;高级工具使用 deepGetText&quot;]
shadow_utils --&gt; selection_toolbar[&quot;selection-toolbar.js&lt;br/&gt;选择区域工具栏&quot;]
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/shadow-dom-utils.js#L1-L443" target="_blank" rel="noreferrer">src/content/shadow-dom-utils.js#L1-L443</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/page-interaction.js#L1-L10" target="_blank" rel="noreferrer">src/content/page-interaction.js#L1-L10</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/interaction-tools.js#L1-L6" target="_blank" rel="noreferrer">src/content/interaction-tools.js#L1-L6</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/page-tools.js#L59-L108" target="_blank" rel="noreferrer">src/content/page-tools.js#L59-L108</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/advanced-tools.js#L4" target="_blank" rel="noreferrer">src/content/advanced-tools.js#L4</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/selection-toolbar.js#L3" target="_blank" rel="noreferrer">src/content/selection-toolbar.js#L3</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/shadow-dom-utils.js#L1-L443" target="_blank" rel="noreferrer">src/content/shadow-dom-utils.js#L1-L443</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/page-interaction.js#L1-L10" target="_blank" rel="noreferrer">src/content/page-interaction.js#L1-L10</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/interaction-tools.js#L1-L6" target="_blank" rel="noreferrer">src/content/interaction-tools.js#L1-L6</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/page-tools.js#L59-L108" target="_blank" rel="noreferrer">src/content/page-tools.js#L59-L108</a></li></ul><h2 id="核心组件与职责划分" tabindex="-1">核心组件与职责划分 <a class="header-anchor" href="#核心组件与职责划分" aria-label="Permalink to &quot;核心组件与职责划分&quot;">​</a></h2><p>Shadow DOM 穿透相关代码按“底层遍历工具 + 上层交互工具”分层组织。</p><table tabindex="0"><thead><tr><th>模块</th><th>主要职责</th><th>关键函数或行为</th></tr></thead><tbody><tr><td><code>shadow-dom-utils.js</code></td><td>提供递归穿透 Shadow DOM 和同源 iframe 的基础能力</td><td><code>deepQuerySelector</code>、<code>deepQuerySelectorAll</code>、<code>deepGetText</code>、<code>deepGetHtml</code>、<code>getDeepSelector</code>、<code>findShadowRoot</code>、<code>attachSelectionListeners</code></td></tr><tr><td><code>page-interaction.js</code></td><td>构建可交互元素快照、分配 ref、解析 ref、渲染交互树</td><td><code>queryInteractiveElements</code>、<code>collectSnapshotOps</code>、<code>resolveByRef</code>、<code>interactByRef</code></td></tr><tr><td><code>interaction-tools.js</code></td><td>面向模型或工具的原子操作：点击、填充表单、键盘输入、滚动、等待状态</td><td><code>clickElement</code>、<code>fillForm</code>、<code>keyboardInput</code>、<code>scrollToPosition</code>、<code>waitForElement</code>、<code>clickByText</code></td></tr><tr><td><code>page-tools.js</code></td><td>页面级信息导出：标题、URL、正文、标题列表、链接、完整 HTML</td><td><code>getPageInfo</code>、<code>getFullHtml</code></td></tr><tr><td><code>advanced-tools.js</code></td><td>高级工具入口，复用 <code>deepGetText</code> 做内容读取</td><td>使用 <code>deepGetText</code></td></tr><tr><td><code>selection-toolbar.js</code></td><td>选择区域工具栏，依赖 Shadow DOM 内的选择变化</td><td><code>deepGetSelection</code>、<code>getRangeViewportPosition</code>、<code>attachSelectionListeners</code></td></tr></tbody></table><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/shadow-dom-utils.js#L12-L86" target="_blank" rel="noreferrer">src/content/shadow-dom-utils.js#L12-L86</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/page-interaction.js#L51-L152" target="_blank" rel="noreferrer">src/content/page-interaction.js#L51-L152</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/interaction-tools.js#L100-L148" target="_blank" rel="noreferrer">src/content/interaction-tools.js#L100-L148</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/page-tools.js#L59-L108" target="_blank" rel="noreferrer">src/content/page-tools.js#L59-L108</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/selection-toolbar.js#L3" target="_blank" rel="noreferrer">src/content/selection-toolbar.js#L3</a></li></ul><h2 id="架构总览-从工具调用到-shadow-root-遍历" tabindex="-1">架构总览：从工具调用到 Shadow Root 遍历 <a class="header-anchor" href="#架构总览-从工具调用到-shadow-root-遍历" aria-label="Permalink to &quot;架构总览：从工具调用到 Shadow Root 遍历&quot;">​</a></h2><p>以“点击按钮”为例，调用链会经过工具层、选择器穿透层、DOM 操作层，并最终触发目标元素的交互逻辑。</p><pre class="mermaid">sequenceDiagram
participant Caller as &quot;调用方&quot;
participant InteractionTools as &quot;interaction-tools.js&quot;
participant PageInteraction as &quot;page-interaction.js&quot;
participant ShadowUtils as &quot;shadow-dom-utils.js&quot;
participant Target as &quot;目标元素&quot;
Caller-&gt;&gt;InteractionTools : &quot;clickElement(selector)&quot;
InteractionTools-&gt;&gt;ShadowUtils : &quot;deepQuerySelector(selector)&quot;
ShadowUtils--&gt;&gt;InteractionTools : &quot;返回元素或 null&quot;
InteractionTools-&gt;&gt;Target : &quot;element.click()&quot;
InteractionTools-&gt;&gt;InteractionTools : &quot;autoWaitAfterAction(检测导航/DOM 变化)&quot;
InteractionTools--&gt;&gt;Caller : &quot;成功结果 + 等待信息&quot;
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/interaction-tools.js#L106-L148" target="_blank" rel="noreferrer">src/content/interaction-tools.js#L106-L148</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/shadow-dom-utils.js#L12-L45" target="_blank" rel="noreferrer">src/content/shadow-dom-utils.js#L12-L45</a></li></ul><p>另一个典型流程是“按文本点击”，它会先通过 <code>deepQuerySelectorAll</code> 遍历所有候选元素，再匹配文本、检查可见性并执行点击。</p><pre class="mermaid">sequenceDiagram
participant Caller as &quot;调用方&quot;
participant InteractionTools as &quot;interaction-tools.js&quot;
participant ShadowUtils as &quot;shadow-dom-utils.js&quot;
participant Target as &quot;目标元素&quot;
Caller-&gt;&gt;InteractionTools : &quot;clickByText(text, options)&quot;
InteractionTools-&gt;&gt;ShadowUtils : &quot;deepQuerySelectorAll(多个选择器)&quot;
ShadowUtils--&gt;&gt;InteractionTools : &quot;候选元素集合&quot;
InteractionTools-&gt;&gt;InteractionTools : &quot;匹配文本 + 可见性检查&quot;
InteractionTools-&gt;&gt;Target : &quot;dispatchEvent / click()&quot;
InteractionTools-&gt;&gt;InteractionTools : &quot;autoWaitAfterAction&quot;
InteractionTools--&gt;&gt;Caller : &quot;命中结果或诊断错误&quot;
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/interaction-tools.js#L534-L657" target="_blank" rel="noreferrer">src/content/interaction-tools.js#L534-L657</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/shadow-dom-utils.js#L56-L86" target="_blank" rel="noreferrer">src/content/shadow-dom-utils.js#L56-L86</a></li></ul><h2 id="穿透算法详解" tabindex="-1">穿透算法详解 <a class="header-anchor" href="#穿透算法详解" aria-label="Permalink to &quot;穿透算法详解&quot;">​</a></h2><h3 id="递归遍历-shadow-root" tabindex="-1">递归遍历 Shadow Root <a class="header-anchor" href="#递归遍历-shadow-root" aria-label="Permalink to &quot;递归遍历 Shadow Root&quot;">​</a></h3><p><code>deepQuerySelector</code> 和 <code>deepQuerySelectorAll</code> 是穿透能力的核心。它们的工作方式是：</p><ol><li>如果当前根节点支持 <code>querySelectorAll</code>，则遍历所有子元素。</li><li>对每个有 <code>shadowRoot</code> 的元素，递归进入 Shadow Root 继续搜索。</li><li>对 <code>IFRAME</code> 或 <code>FRAME</code> 元素，尝试读取 <code>contentDocument</code> 或 <code>contentWindow.document</code>，并递归进入同源文档。</li><li>在 Shadow DOM 和 iframe 优先搜索后，再在当前根节点上执行一次选择器匹配。</li><li>最大递归深度默认是 5，防止无限嵌套导致性能问题。</li></ol><pre class="mermaid">flowchart TD
Start([&quot;开始&quot;]) --&gt; CheckDepth[&quot;检查当前深度是否超过最大深度&quot;]
CheckDepth --&gt; |超过| ReturnNull[&quot;返回空结果&quot;]
CheckDepth --&gt; |未超过| QueryAll[&quot;遍历当前根的所有元素&quot;]
QueryAll --&gt; HasShadow{&quot;元素是否有 shadowRoot&quot;}
HasShadow --&gt; |是| RecurseShadow[&quot;递归进入 shadowRoot 搜索&quot;]
RecurseShadow --&gt; FoundShadow{&quot;Shadow 中找到目标&quot;}
FoundShadow --&gt; |是| ReturnFound[&quot;返回找到的元素&quot;]
FoundShadow --&gt; |否| NextEl[&quot;继续下一个元素&quot;]
HasShadow --&gt; |否| IsIframe{&quot;是否为 IFRAME 或 FRAME&quot;}
IsIframe --&gt; |是| TryIframe[&quot;尝试读取 contentDocument&quot;]
TryIframe --&gt; CanAccess{&quot;能否访问文档&quot;}
CanAccess --&gt; |能| RecurseIframe[&quot;递归进入 iframe 文档&quot;]
CanAccess --&gt; |不能| SkipIframe[&quot;跳过跨域 iframe&quot;]
IsIframe --&gt; |否| NextEl
NextEl --&gt; Continue[&quot;继续遍历&quot;]
Continue --&gt; AfterTraversal[&quot;遍历完成后在当前根执行选择器&quot;]
AfterTraversal --&gt; HasResult{&quot;当前根找到结果&quot;}
HasResult --&gt; |是| ReturnCurrent[&quot;返回当前根结果&quot;]
HasResult --&gt; |否| End([&quot;结束&quot;])
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/shadow-dom-utils.js#L12-L45" target="_blank" rel="noreferrer">src/content/shadow-dom-utils.js#L12-L45</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/shadow-dom-utils.js#L56-L86" target="_blank" rel="noreferrer">src/content/shadow-dom-utils.js#L56-L86</a></li></ul><h3 id="样式隔离处理" tabindex="-1">样式隔离处理 <a class="header-anchor" href="#样式隔离处理" aria-label="Permalink to &quot;样式隔离处理&quot;">​</a></h3><p>Shadow DOM 的样式隔离意味着宿主页面的 CSS 通常不会直接影响组件内部样式，反之亦然。本项目的穿透能力并不直接修改 Shadow DOM 内部样式，而是通过以下方式间接适配样式隔离：</p><ul><li>使用 <code>innerText</code>、<code>textContent</code>、<code>innerHTML</code>、<code>outerHTML</code> 读取文本和 HTML。</li><li>使用 <code>getBoundingClientRect</code>、<code>checkVisibility</code>、<code>getComputedStyle</code> 判断可见性和布局。</li><li>使用 <code>getRootNode</code> 判断元素是否位于 Shadow Root 内。</li><li>生成包含 Shadow Host 路径的选择器时，使用自定义前缀标记 Shadow DOM 层级。</li></ul><p>这种方式避免了直接注入样式破坏组件内部样式隔离，同时保证外部工具能正确识别元素位置和可见性。</p><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/shadow-dom-utils.js#L135-L173" target="_blank" rel="noreferrer">src/content/shadow-dom-utils.js#L135-L173</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/shadow-dom-utils.js#L183-L232" target="_blank" rel="noreferrer">src/content/shadow-dom-utils.js#L183-L232</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/shadow-dom-utils.js#L239-L284" target="_blank" rel="noreferrer">src/content/shadow-dom-utils.js#L239-L284</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/page-interaction.js#L205-L223" target="_blank" rel="noreferrer">src/content/page-interaction.js#L205-L223</a></li></ul><h3 id="事件冒泡机制" tabindex="-1">事件冒泡机制 <a class="header-anchor" href="#事件冒泡机制" aria-label="Permalink to &quot;事件冒泡机制&quot;">​</a></h3><p>Shadow DOM 的事件模型允许某些事件冒泡到宿主文档，但事件目标仍保持在 Shadow Tree 内部。本项目在以下场景中考虑了事件冒泡：</p><ul><li>点击、悬停、键盘输入等操作都会显式派发 <code>bubbles: true</code> 的事件，以便 React、Vue、Angular 等框架的合成事件系统能够捕获。</li><li>选择变化监听器通过 <code>attachSelectionListeners</code> 递归挂载到 Shadow Root，确保用户在选择 Shadow DOM 内部文本时也能触发工具栏更新。</li><li>表单填充时使用原生 setter 设置值，并派发 <code>input</code>、<code>change</code> 事件，绕过受控组件的状态隔离。</li></ul><pre class="mermaid">sequenceDiagram
participant User as &quot;用户&quot;
participant ShadowHost as &quot;Shadow Host&quot;
participant ShadowRoot as &quot;Shadow Root&quot;
participant InternalEl as &quot;内部元素&quot;
participant ContentScript as &quot;Content Script&quot;
User-&gt;&gt;InternalEl : &quot;点击内部元素&quot;
InternalEl-&gt;&gt;ShadowRoot : &quot;触发内部事件&quot;
ShadowRoot-&gt;&gt;ShadowHost : &quot;冒泡到宿主&quot;
ShadowHost-&gt;&gt;ContentScript : &quot;Content Script 监听或派发合成事件&quot;
ContentScript-&gt;&gt;InternalEl : &quot;dispatchEvent(input/change/click)&quot;
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/interaction-tools.js#L431-L444" target="_blank" rel="noreferrer">src/content/interaction-tools.js#L431-L444</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/shadow-dom-utils.js#L388-L408" target="_blank" rel="noreferrer">src/content/shadow-dom-utils.js#L388-L408</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/interaction-tools.js#L431-L444" target="_blank" rel="noreferrer">src/content/interaction-tools.js#L431-L444</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/shadow-dom-utils.js#L388-L408" target="_blank" rel="noreferrer">src/content/shadow-dom-utils.js#L388-L408</a></li></ul><h2 id="跨域-iframe-与安全边界" tabindex="-1">跨域 iframe 与安全边界 <a class="header-anchor" href="#跨域-iframe-与安全边界" aria-label="Permalink to &quot;跨域 iframe 与安全边界&quot;">​</a></h2><p>Shadow DOM 本身不是跨域问题，但项目中同时处理了 <code>iframe</code> 和 <code>Shadow DOM</code>。对于 <code>iframe</code>：</p><ul><li>如果 <code>contentDocument</code> 或 <code>contentWindow.document</code> 可访问，说明是同域或扩展权限允许访问，工具会继续递归遍历。</li><li>如果访问抛出异常，代码会捕获并跳过该 iframe，避免中断整个遍历过程。</li><li>这种设计符合浏览器的同源策略：跨域文档不可直接读写，只能作为黑盒存在。</li></ul><p>对于 Shadow DOM：</p><ul><li>只要当前 Content Script 能访问宿主元素，就能读取其 <code>shadowRoot</code>。</li><li>如果宿主元素本身不可访问，则无法进入 Shadow Tree。</li><li>工具通过 try-catch 包裹可能失败的 DOM 访问，保证局部失败不影响整体遍历。</li></ul><pre class="mermaid">flowchart TD
Start([&quot;开始遍历&quot;]) --&gt; CheckIframe{&quot;是否遇到 iframe&quot;}
CheckIframe --&gt; |否| CheckShadow{&quot;是否遇到 shadowRoot&quot;}
CheckShadow --&gt; |是| EnterShadow[&quot;递归进入 Shadow Root&quot;]
CheckShadow --&gt; |否| Continue[&quot;继续遍历&quot;]
CheckIframe --&gt; |是| TryAccess[&quot;尝试访问 contentDocument&quot;]
TryAccess --&gt; AccessOK{&quot;访问成功&quot;}
AccessOK --&gt; |是| EnterIframe[&quot;递归进入 iframe 文档&quot;]
AccessOK --&gt; |否| SkipIframe[&quot;记录跨域限制并跳过&quot;]
EnterShadow --&gt; Continue
EnterIframe --&gt; Continue
SkipIframe --&gt; Continue
Continue --&gt; End([&quot;结束&quot;])
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/shadow-dom-utils.js#L23-L33" target="_blank" rel="noreferrer">src/content/shadow-dom-utils.js#L23-L33</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/shadow-dom-utils.js#L69-L78" target="_blank" rel="noreferrer">src/content/shadow-dom-utils.js#L69-L78</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/shadow-dom-utils.js#L23-L33" target="_blank" rel="noreferrer">src/content/shadow-dom-utils.js#L23-L33</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/shadow-dom-utils.js#L69-L78" target="_blank" rel="noreferrer">src/content/shadow-dom-utils.js#L69-L78</a></li></ul><h2 id="web-components-内部内容访问示例" tabindex="-1">Web Components 内部内容访问示例 <a class="header-anchor" href="#web-components-内部内容访问示例" aria-label="Permalink to &quot;Web Components 内部内容访问示例&quot;">​</a></h2><p>本节给出在实际使用中如何操作组件内部元素、读取组件状态和触发组件方法。为避免泄露具体实现细节，这里以“步骤 + 对应源码位置”的方式说明。</p><h3 id="示例一-点击-shadow-dom-内部的按钮" tabindex="-1">示例一：点击 Shadow DOM 内部的按钮 <a class="header-anchor" href="#示例一-点击-shadow-dom-内部的按钮" aria-label="Permalink to &quot;示例一：点击 Shadow DOM 内部的按钮&quot;">​</a></h3><p>适用场景：页面外层有一个普通按钮，但真正可用的按钮在某个 Web Component 的 Shadow Root 中。</p><p>推荐步骤：</p><ol><li>使用 <code>deepQuerySelector</code> 传入目标选择器。</li><li>如果返回元素为空，说明选择器无法穿透 Shadow DOM。</li><li>调整选择器或使用 <code>query_elements</code> 生成的 ref。</li><li>调用 <code>clickElement</code> 或 <code>interactByRef</code> 执行点击。</li></ol><p>参考路径：</p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/shadow-dom-utils.js#L12-L45" target="_blank" rel="noreferrer">src/content/shadow-dom-utils.js#L12-L45</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/interaction-tools.js#L106-L148" target="_blank" rel="noreferrer">src/content/interaction-tools.js#L106-L148</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/page-interaction.js#L793-L800" target="_blank" rel="noreferrer">src/content/page-interaction.js#L793-L800</a></li></ul><h3 id="示例二-读取-shadow-dom-内部文本" tabindex="-1">示例二：读取 Shadow DOM 内部文本 <a class="header-anchor" href="#示例二-读取-shadow-dom-内部文本" aria-label="Permalink to &quot;示例二：读取 Shadow DOM 内部文本&quot;">​</a></h3><p>适用场景：需要判断组件是否显示“订单已确认”之类的状态文本。</p><p>推荐步骤：</p><ol><li>使用 <code>deepGetText</code> 获取包含 Shadow DOM 和同源 iframe 的合并文本。</li><li>在业务逻辑中判断目标字符串是否存在。</li><li>如果需要更精确的结构信息，使用 <code>deepGetHtml</code> 获取带注释标记的 HTML。</li></ol><p>参考路径：</p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/shadow-dom-utils.js#L135-L173" target="_blank" rel="noreferrer">src/content/shadow-dom-utils.js#L135-L173</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/shadow-dom-utils.js#L183-L232" target="_blank" rel="noreferrer">src/content/shadow-dom-utils.js#L183-L232</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/test/unit/completion-evidence-content.unit.test.js#L51-L57" target="_blank" rel="noreferrer">test/unit/completion-evidence-content.unit.test.js#L51-L57</a></li></ul><h3 id="示例三-填充-shadow-dom-内部的表单" tabindex="-1">示例三：填充 Shadow DOM 内部的表单 <a class="header-anchor" href="#示例三-填充-shadow-dom-内部的表单" aria-label="Permalink to &quot;示例三：填充 Shadow DOM 内部的表单&quot;">​</a></h3><p>适用场景：React 受控组件、富文本编辑器、自定义下拉框。</p><p>推荐步骤：</p><ol><li>优先使用 <code>query_elements</code> 返回的 ref，避免手写脆弱选择器。</li><li>如果是标准 input/textarea，使用 <code>setNativeValue</code> 设置值并派发 <code>input</code>、<code>change</code>。</li><li>如果是 <code>contenteditable</code> 或富文本编辑器，使用 <code>fillContentEditable</code>。</li><li>如果是自定义下拉，使用 <code>selectDropdown</code> 或先点击触发器再匹配选项。</li></ol><p>参考路径：</p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/interaction-tools.js#L153-L241" target="_blank" rel="noreferrer">src/content/interaction-tools.js#L153-L241</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/interaction-tools.js#L399-L476" target="_blank" rel="noreferrer">src/content/interaction-tools.js#L399-L476</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/interaction-tools.js#L666-L739" target="_blank" rel="noreferrer">src/content/interaction-tools.js#L666-L739</a></li></ul><h3 id="示例四-获取元素在视口中的坐标" tabindex="-1">示例四：获取元素在视口中的坐标 <a class="header-anchor" href="#示例四-获取元素在视口中的坐标" aria-label="Permalink to &quot;示例四：获取元素在视口中的坐标&quot;">​</a></h3><p>适用场景：工具栏、悬浮提示、截图标注需要知道元素位置。</p><p>推荐步骤：</p><ol><li>使用 <code>getElementViewportPosition</code> 获取元素中心点坐标。</li><li>如果目标是 Range，使用 <code>getRangeViewportPosition</code>。</li><li>注意 iframe 偏移会被自动累加。</li></ol><p>参考路径：</p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/shadow-dom-utils.js#L311-L331" target="_blank" rel="noreferrer">src/content/shadow-dom-utils.js#L311-L331</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/shadow-dom-utils.js#L338-L377" target="_blank" rel="noreferrer">src/content/shadow-dom-utils.js#L338-L377</a></li></ul><h3 id="示例五-生成包含-shadow-dom-的路径选择器" tabindex="-1">示例五：生成包含 Shadow DOM 的路径选择器 <a class="header-anchor" href="#示例五-生成包含-shadow-dom-的路径选择器" aria-label="Permalink to &quot;示例五：生成包含 Shadow DOM 的路径选择器&quot;">​</a></h3><p>适用场景：调试、日志、快照重建时需要表达元素在 Shadow Host 中的位置。</p><p>推荐步骤：</p><ol><li>使用 <code>getDeepSelector</code> 生成路径。</li><li>如果元素在 Shadow Root 中，返回值会以 <code>shadow(...)</code> 前缀开头。</li><li>消费方可根据前缀决定是否重新解析 Shadow Host。</li></ol><p>参考路径：</p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/shadow-dom-utils.js#L239-L284" target="_blank" rel="noreferrer">src/content/shadow-dom-utils.js#L239-L284</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/shadow-dom-utils.js#L12-L45" target="_blank" rel="noreferrer">src/content/shadow-dom-utils.js#L12-L45</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/shadow-dom-utils.js#L135-L173" target="_blank" rel="noreferrer">src/content/shadow-dom-utils.js#L135-L173</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/shadow-dom-utils.js#L183-L232" target="_blank" rel="noreferrer">src/content/shadow-dom-utils.js#L183-L232</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/shadow-dom-utils.js#L239-L284" target="_blank" rel="noreferrer">src/content/shadow-dom-utils.js#L239-L284</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/shadow-dom-utils.js#L311-L377" target="_blank" rel="noreferrer">src/content/shadow-dom-utils.js#L311-L377</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/interaction-tools.js#L106-L148" target="_blank" rel="noreferrer">src/content/interaction-tools.js#L106-L148</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/interaction-tools.js#L153-L241" target="_blank" rel="noreferrer">src/content/interaction-tools.js#L153-L241</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/interaction-tools.js#L399-L476" target="_blank" rel="noreferrer">src/content/interaction-tools.js#L399-L476</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/interaction-tools.js#L666-L739" target="_blank" rel="noreferrer">src/content/interaction-tools.js#L666-L739</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/test/unit/completion-evidence-content.unit.test.js#L51-L57" target="_blank" rel="noreferrer">test/unit/completion-evidence-content.unit.test.js#L51-L57</a></li></ul><h2 id="性能、缓存与内存泄漏防护" tabindex="-1">性能、缓存与内存泄漏防护 <a class="header-anchor" href="#性能、缓存与内存泄漏防护" aria-label="Permalink to &quot;性能、缓存与内存泄漏防护&quot;">​</a></h2><h3 id="遍历优化" tabindex="-1">遍历优化 <a class="header-anchor" href="#遍历优化" aria-label="Permalink to &quot;遍历优化&quot;">​</a></h3><ul><li>最大递归深度默认限制为 5，避免深层嵌套导致栈溢出或长时间遍历。</li><li><code>deepQuerySelector</code> 在 Shadow DOM 中优先返回第一个匹配项，减少不必要遍历。</li><li><code>deepQuerySelectorAll</code> 使用 <code>Set</code> 去重，避免同一元素被多次加入结果。</li><li><code>deepGetText</code> 和 <code>deepGetHtml</code> 使用 <code>visited</code> Set 防止循环引用。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/shadow-dom-utils.js#L12-L13" target="_blank" rel="noreferrer">src/content/shadow-dom-utils.js#L12-L13</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/shadow-dom-utils.js#L56-L86" target="_blank" rel="noreferrer">src/content/shadow-dom-utils.js#L56-L86</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/shadow-dom-utils.js#L135-L137" target="_blank" rel="noreferrer">src/content/shadow-dom-utils.js#L135-L137</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/shadow-dom-utils.js#L183-L185" target="_blank" rel="noreferrer">src/content/shadow-dom-utils.js#L183-L185</a></li></ul><h3 id="缓存策略" tabindex="-1">缓存策略 <a class="header-anchor" href="#缓存策略" aria-label="Permalink to &quot;缓存策略&quot;">​</a></h3><ul><li><code>page-interaction.js</code> 使用 <code>WeakMap</code> 将 Element 映射到 ref 编号，实现跨快照复用稳定编号。</li><li><code>elementRegistry</code> 保存最近一次快照的 ref 到元素信息的映射，便于快速解析和兜底重查。</li><li>selector 懒生成：仅在需要时才调用 <code>generateUniqueSelector</code>，降低注册阶段开销。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/page-interaction.js#L51-L83" target="_blank" rel="noreferrer">src/content/page-interaction.js#L51-L83</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/page-interaction.js#L89-L106" target="_blank" rel="noreferrer">src/content/page-interaction.js#L89-L106</a></li></ul><h3 id="内存泄漏防护" tabindex="-1">内存泄漏防护 <a class="header-anchor" href="#内存泄漏防护" aria-label="Permalink to &quot;内存泄漏防护&quot;">​</a></h3><ul><li><code>attachSelectionListeners</code> 返回已添加监听器的集合，配合 <code>removeSelectionListeners</code> 统一移除。</li><li>监听器对象包含 root 和 listener 引用，移除后清空集合，避免残留引用。</li><li>Shadow DOM 选择变化监听器递归挂载，但通过 <code>listeners.has(root)</code> 防止重复挂载。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/shadow-dom-utils.js#L388-L423" target="_blank" rel="noreferrer">src/content/shadow-dom-utils.js#L388-L423</a></li></ul><h3 id="大页面与大数据风险" tabindex="-1">大页面与大数据风险 <a class="header-anchor" href="#大页面与大数据风险" aria-label="Permalink to &quot;大页面与大数据风险&quot;">​</a></h3><ul><li><code>deepGetHtml</code> 会拼接 Shadow DOM 和 iframe 的完整 HTML，可能产生巨大字符串。</li><li><code>deepGetText</code> 会合并多层文本，适合摘要或判断，不适合直接传给大型上下文。</li><li>建议对长页面使用分页、截断、只读必要字段等策略。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/shadow-dom-utils.js#L183-L232" target="_blank" rel="noreferrer">src/content/shadow-dom-utils.js#L183-L232</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/shadow-dom-utils.js#L135-L173" target="_blank" rel="noreferrer">src/content/shadow-dom-utils.js#L135-L173</a></li></ul><h2 id="与现代前端框架的集成实践" tabindex="-1">与现代前端框架的集成实践 <a class="header-anchor" href="#与现代前端框架的集成实践" aria-label="Permalink to &quot;与现代前端框架的集成实践&quot;">​</a></h2><h3 id="react" tabindex="-1">React <a class="header-anchor" href="#react" aria-label="Permalink to &quot;React&quot;">​</a></h3><ul><li>React 使用合成事件系统，因此直接调用 <code>element.click()</code> 有时不足以触发受控组件状态更新。</li><li>本项目在表单填充和键盘输入中显式派发 <code>input</code>、<code>change</code>、<code>keydown</code>、<code>keyup</code> 等事件，并尽量使用 <code>InputEvent</code> 携带 <code>inputType</code>。</li><li>对于受控组件，优先使用 <code>setNativeValue</code> 设置原生值，再派发事件，绕过 React 内部状态隔离。</li></ul><p>推荐实践：</p><ul><li>优先使用 <code>query_elements</code> 返回的 ref，避免手写选择器。</li><li>输入类操作使用 <code>fillForm</code> 或 <code>keyboardInput</code>。</li><li>点击类操作使用 <code>clickElement</code> 或 <code>clickByText</code>。</li></ul><p>参考路径：</p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/interaction-tools.js#L172-L183" target="_blank" rel="noreferrer">src/content/interaction-tools.js#L172-L183</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/interaction-tools.js#L431-L444" target="_blank" rel="noreferrer">src/content/interaction-tools.js#L431-L444</a></li></ul><h3 id="vue" tabindex="-1">Vue <a class="header-anchor" href="#vue" aria-label="Permalink to &quot;Vue&quot;">​</a></h3><ul><li>Vue 模板编译后通常生成真实 DOM，但第三方 UI 库可能使用 Shadow DOM。</li><li>对于第三方组件，优先使用 <code>deepQuerySelector</code> 或 <code>deepQuerySelectorAll</code>。</li><li>对于 Vue 自身组件，优先通过 ref 或组件暴露的方法；若只能操作 DOM，则使用本项目提供的工具。</li></ul><p>参考路径：</p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/shadow-dom-utils.js#L12-L45" target="_blank" rel="noreferrer">src/content/shadow-dom-utils.js#L12-L45</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/interaction-tools.js#L106-L148" target="_blank" rel="noreferrer">src/content/interaction-tools.js#L106-L148</a></li></ul><h3 id="angular" tabindex="-1">Angular <a class="header-anchor" href="#angular" aria-label="Permalink to &quot;Angular&quot;">​</a></h3><ul><li>Angular 组件通常不强制使用 Shadow DOM，但 Material 等库可能引入隔离样式或自定义元素。</li><li>对于自定义元素，使用 <code>deepQuerySelector</code> 穿透。</li><li>对于表单控件，使用 <code>fillForm</code> 的 <code>checkbox</code>、<code>radio</code>、<code>select</code> 分支，避免 Angular 双向绑定失效。</li></ul><p>参考路径：</p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/interaction-tools.js#L188-L225" target="_blank" rel="noreferrer">src/content/interaction-tools.js#L188-L225</a></li></ul><h3 id="通用最佳实践" tabindex="-1">通用最佳实践 <a class="header-anchor" href="#通用最佳实践" aria-label="Permalink to &quot;通用最佳实践&quot;">​</a></h3><ol><li>优先使用 <code>query_elements</code> 生成的 ref，而不是手写 CSS 选择器。</li><li>对复杂组件，先用 <code>deepGetText</code> 或 <code>deepGetHtml</code> 观察内部结构。</li><li>对受控组件，优先设置原生值并派发事件，不要只改 <code>value</code>。</li><li>对 Shadow DOM 内部选择，使用 <code>deepQuerySelectorAll</code> 并过滤可见元素。</li><li>对跨域 iframe，接受“不可访问”的降级结果，不要强行绕过浏览器安全策略。</li></ol><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/interaction-tools.js#L172-L225" target="_blank" rel="noreferrer">src/content/interaction-tools.js#L172-L225</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/interaction-tools.js#L431-L444" target="_blank" rel="noreferrer">src/content/interaction-tools.js#L431-L444</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/shadow-dom-utils.js#L12-L45" target="_blank" rel="noreferrer">src/content/shadow-dom-utils.js#L12-L45</a></li></ul><h2 id="故障排查指南" tabindex="-1">故障排查指南 <a class="header-anchor" href="#故障排查指南" aria-label="Permalink to &quot;故障排查指南&quot;">​</a></h2><h3 id="常见问题一-选择器找不到元素" tabindex="-1">常见问题一：选择器找不到元素 <a class="header-anchor" href="#常见问题一-选择器找不到元素" aria-label="Permalink to &quot;常见问题一：选择器找不到元素&quot;">​</a></h3><p>现象：<code>deepQuerySelector</code> 返回 null。</p><p>可能原因：</p><ul><li>元素在 Shadow DOM 内部，但选择器没有覆盖 Shadow Host。</li><li>元素尚未渲染完成。</li><li>元素被隐藏或不在可视区域。</li><li>元素在跨域 iframe 中。</li></ul><p>排查建议：</p><ol><li>使用 <code>hasShadowDom</code> 判断页面是否包含 Shadow DOM。</li><li>使用 <code>deepGetHtml</code> 查看 Shadow DOM 和 iframe 的 HTML 结构。</li><li>使用 <code>query_elements</code> 获取结构化快照，确认元素是否被识别为可交互元素。</li><li>对 iframe，检查是否同源。</li></ol><p>参考路径：</p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/shadow-dom-utils.js#L429-L443" target="_blank" rel="noreferrer">src/content/shadow-dom-utils.js#L429-L443</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/shadow-dom-utils.js#L183-L232" target="_blank" rel="noreferrer">src/content/shadow-dom-utils.js#L183-L232</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/page-interaction.js#L410-L440" target="_blank" rel="noreferrer">src/content/page-interaction.js#L410-L440</a></li></ul><h3 id="常见问题二-点击无效或状态未更新" tabindex="-1">常见问题二：点击无效或状态未更新 <a class="header-anchor" href="#常见问题二-点击无效或状态未更新" aria-label="Permalink to &quot;常见问题二：点击无效或状态未更新&quot;">​</a></h3><p>现象：点击成功，但 React/Vue/Angular 组件状态未更新。</p><p>可能原因：</p><ul><li>只调用了 <code>click()</code>，没有派发框架依赖的事件。</li><li>使用了 jQuery 或旧式赋值方式，绕过了框架状态。</li><li>目标元素是 <code>contenteditable</code> 或富文本编辑器。</li></ul><p>排查建议：</p><ol><li>使用 <code>clickElement</code> 或 <code>interactByRef</code>。</li><li>对输入类操作使用 <code>fillForm</code> 或 <code>keyboardInput</code>。</li><li>对富文本编辑器使用 <code>fillContentEditable</code>。</li></ol><p>参考路径：</p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/interaction-tools.js#L106-L148" target="_blank" rel="noreferrer">src/content/interaction-tools.js#L106-L148</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/interaction-tools.js#L172-L183" target="_blank" rel="noreferrer">src/content/interaction-tools.js#L172-L183</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/interaction-tools.js#L399-L476" target="_blank" rel="noreferrer">src/content/interaction-tools.js#L399-L476</a></li></ul><h3 id="常见问题三-选择区域工具栏不响应-shadow-dom-选择" tabindex="-1">常见问题三：选择区域工具栏不响应 Shadow DOM 选择 <a class="header-anchor" href="#常见问题三-选择区域工具栏不响应-shadow-dom-选择" aria-label="Permalink to &quot;常见问题三：选择区域工具栏不响应 Shadow DOM 选择&quot;">​</a></h3><p>现象：用户在 Shadow DOM 内部选中文本，但工具栏没有更新。</p><p>可能原因：</p><ul><li>选择变化监听器未挂载到 Shadow Root。</li><li>监听器被提前移除。</li><li>当前文档不是 Shadow Root。</li></ul><p>排查建议：</p><ol><li>使用 <code>attachSelectionListeners</code> 递归挂载监听器。</li><li>使用 <code>removeSelectionListeners</code> 清理监听器。</li><li>使用 <code>deepGetSelection</code> 获取 Shadow DOM 内的选择内容。</li></ol><p>参考路径：</p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/shadow-dom-utils.js#L95-L125" target="_blank" rel="noreferrer">src/content/shadow-dom-utils.js#L95-L125</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/shadow-dom-utils.js#L388-L423" target="_blank" rel="noreferrer">src/content/shadow-dom-utils.js#L388-L423</a></li></ul><h3 id="常见问题四-跨域-iframe-无法读取内容" tabindex="-1">常见问题四：跨域 iframe 无法读取内容 <a class="header-anchor" href="#常见问题四-跨域-iframe-无法读取内容" aria-label="Permalink to &quot;常见问题四：跨域 iframe 无法读取内容&quot;">​</a></h3><p>现象：遍历到 iframe 后停止或报错。</p><p>可能原因：</p><ul><li>iframe 跨域，浏览器阻止访问 <code>contentDocument</code>。</li><li>扩展权限未配置或页面策略禁止嵌入。</li></ul><p>排查建议：</p><ol><li>接受跨域 iframe 不可访问的限制。</li><li>只对同源 iframe 进行深度遍历。</li><li>如需跨域访问，应通过后端代理或官方 API，而不是绕过浏览器安全策略。</li></ol><p>参考路径：</p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/shadow-dom-utils.js#L23-L33" target="_blank" rel="noreferrer">src/content/shadow-dom-utils.js#L23-L33</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/shadow-dom-utils.js#L69-L78" target="_blank" rel="noreferrer">src/content/shadow-dom-utils.js#L69-L78</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/shadow-dom-utils.js#L95-L125" target="_blank" rel="noreferrer">src/content/shadow-dom-utils.js#L95-L125</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/shadow-dom-utils.js#L183-L232" target="_blank" rel="noreferrer">src/content/shadow-dom-utils.js#L183-L232</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/shadow-dom-utils.js#L388-L423" target="_blank" rel="noreferrer">src/content/shadow-dom-utils.js#L388-L423</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/interaction-tools.js#L106-L148" target="_blank" rel="noreferrer">src/content/interaction-tools.js#L106-L148</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/interaction-tools.js#L172-L183" target="_blank" rel="noreferrer">src/content/interaction-tools.js#L172-L183</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/interaction-tools.js#L399-L476" target="_blank" rel="noreferrer">src/content/interaction-tools.js#L399-L476</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/content/page-interaction.js#L410-L440" target="_blank" rel="noreferrer">src/content/page-interaction.js#L410-L440</a></li></ul><h2 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h2><p>本仓库的 Shadow DOM 穿透能力以 <code>shadow-dom-utils.js</code> 为核心，向上支撑了元素查询、文本提取、HTML 快照、选择区域、可见性判断、滚动收集和 ref 驱动的元素操作。其设计重点包括：</p><ul><li>递归遍历 Shadow Root 和同源 iframe。</li><li>对跨域和权限受限场景做安全降级。</li><li>通过事件派发和原生值设置兼容现代前端框架。</li><li>使用 WeakMap、Set、懒生成 selector 等方式控制性能和内存。</li><li>将 Shadow DOM 能力抽象为可复用的工具模块，避免各功能模块重复实现。</li></ul><p>对于使用者而言，最稳妥的实践是：优先使用 <code>query_elements</code> 返回的 ref，其次使用 <code>deepQuerySelector</code> 和 <code>deepQuerySelectorAll</code>，最后才手写选择器；对受控组件优先使用 <code>fillForm</code>、<code>keyboardInput</code>、<code>clickElement</code> 等高层工具，而不是直接操作 DOM。这样既能穿透 Shadow DOM，又能保持与 React、Vue、Angular 等框架的良好兼容性。</p>`,168)])])}const b=t(i,[["render",l]]);export{p as __pageData,b as default};
